sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    const relatedList = api.context.props.relatedListName;
    if (relatedList === 'sn_grc_metric_metric_definition_threshold')
        api.setState('query', 'metric_definition=' + api.context.props.parentRecordSysId);
    else if (relatedList === 'sn_grc_metric_metric_threshold')
        api.setState('query', 'metric=' + api.context.props.parentRecordSysId);
}
